// Saca el mensaje del sobre de Meta. Los callbacks de estado no traen messages[].
const body = $json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg) return [];
const phone = msg.from;
const name = value.contacts?.[0]?.profile?.name || '';
let text = '';
if (msg.type === 'text') text = msg.text?.body || '';
else if (msg.type === 'interactive') text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
else if (msg.type === 'button') text = msg.button?.text || '';
if (!text.trim()) text = '(el cliente mandó un mensaje sin texto)';
return [{ json: { phone, name, text, msgType: msg.type, msgId: msg.id } }];

const cfg = {};
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.key) cfg[j.key] = j.value;
}
if (!cfg.WHATSAPP_API_VERSION) cfg.WHATSAPP_API_VERSION = 'v18.0';
const msg = $('Extract Message').first().json;

// ---- Horario de atencion -------------------------------------------------
// Martes a domingo 10:00 a 14:00 (America/El_Salvador). Lunes cerrado.
// Lo calculamos aca y no en el prompt: el modelo no tiene reloj y hacer
// aritmetica de fechas con IA es justo donde se equivoca.
const TZ = 'America/El_Salvador';
const ABRE = 10 * 60;
const CIERRA = 14 * 60;
const MARGEN = 45; // si no alcanza a salir antes del cierre, va para el siguiente dia

const partes = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ, weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false,
}).formatToParts(new Date());
const p = Object.fromEntries(partes.map((x) => [x.type, x.value]));
const DIAS = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const dow = DIAS[p.weekday];
const ahoraMin = (Number(p.hour) % 24) * 60 + Number(p.minute);

const NOMBRE = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
const abreEseDia = (d) => d !== 1;
const hhmm = (m) => {
  const h24 = Math.floor(m / 60) % 24;
  const mm = String(m % 60).padStart(2, '0');
  const ampm = h24 < 12 ? 'a.m.' : 'p.m.';
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
  return h12 + ':' + mm + ' ' + ampm;
};

const abierto = abreEseDia(dow) && ahoraMin >= ABRE && ahoraMin < CIERRA;
const alcanzaHoy = abierto && ahoraMin + MARGEN <= CIERRA;

let baseDia = dow;
let baseMin = ahoraMin;
let mismoDia = true;
if (!alcanzaHoy) {
  if (abreEseDia(dow) && ahoraMin < ABRE) {
    baseMin = ABRE;
  } else {
    let d = dow;
    do { d = (d + 1) % 7; } while (!abreEseDia(d));
    baseDia = d;
    baseMin = ABRE;
    mismoDia = false;
  }
}

const cuando = mismoDia
  ? 'hoy'
  : (baseDia === (dow + 1) % 7 ? 'manana' : 'el ' + NOMBRE[baseDia]);

const horario = {
  ahora: NOMBRE[dow] + ' ' + hhmm(ahoraMin),
  estado: abierto ? 'ABIERTO (cerramos a las 2:00 p.m.)' : 'CERRADO',
  inmediato: alcanzaHoy,
  base: cuando + ' a las ' + hhmm(baseMin),
};

return [{ json: { cfg, phone: msg.phone, name: msg.name, text: msg.text, horario } }];

const helpers = this.helpers;
const cfg = $('Merge Config').first().json.cfg;

let items = query.items;
if (typeof items === 'string') {
  try { items = JSON.parse(items); } catch (e) { items = []; }
}
if (!Array.isArray(items) || items.length === 0) {
  return 'ERROR: no mandaste items. Volve a llamar la herramienta con items = [{"sku":"COMBO-ENT","quantity":1}].';
}

const body = {
  source: 'whatsapp',
  customer_phone: String(query.customer_phone || ''),
  customer_name: query.customer_name || 'Cliente WhatsApp',
  // Todo pedido de WhatsApp sale de Sucursal Central, sea retiro o domicilio.
  // Se fija aca a proposito para que el agente no pueda mandarlo al Mercado.
  location_code: 'C',
  order_type: query.order_type || 'pickup',
  payment_method: query.payment_method || 'cash',
  items: items.map((i) => ({ sku: String(i.sku), quantity: Number(i.quantity) || 1 })),
};
if (query.customer_email) body.customer_email = query.customer_email;
if (body.order_type === 'delivery') {
  body.delivery_address = query.delivery_address || '';
  if (query.delivery_zone_id) body.delivery_zone_id = query.delivery_zone_id;
}

try {
  const data = await helpers.httpRequest({
    method: 'POST',
    url: cfg.SUPABASE_URL + '/functions/v1/create-order',
    headers: { 'Content-Type': 'application/json', 'x-webhook-secret': cfg.WHATSAPP_WEBHOOK_SECRET },
    body,
    json: true,
  });
  // Le recordamos al modelo que el link es obligatorio: es el fallo que ya tuvimos.
  if (body.payment_method === 'payment_link') {
    data.INSTRUCCION = data.payment_url
      ? 'OBLIGATORIO: pegue payment_url completo en el mismo mensaje de confirmacion.'
      : 'No se genero link de pago. Digaselo al cliente y ofrezca efectivo.';
  }
  return JSON.stringify(data);
} catch (e) {
  const d = (e && e.response && e.response.body) ? e.response.body : (e && e.message ? e.message : String(e));
  return JSON.stringify({ error: true, detalle: d });
}

