// La respuesta del agente sale en $json.output. Si el agente falló, mandamos un fallback.
const phone = $('Extract Message').first().json.phone;
let text = ($json.output || '').toString().trim();
if (!text) {
  text = 'Uy, se me trabó el sistema un momento 😅 Volvé a escribirme porfa, o escribí "operador" para hablar con el equipo.';
}
// WhatsApp corta en 4096 caracteres
const chunks = [];
while (text.length > 4000) {
  let cut = text.lastIndexOf('\n', 4000);
  if (cut < 2000) cut = 4000;
  chunks.push(text.slice(0, cut));
  text = text.slice(cut).trim();
}
if (text) chunks.push(text);
return chunks.map(c => ({ json: { to: phone, text: c } }));

const q = $('Webhook Verify (GET) v2').first().json.query || {};
let token = ($json && $json.key === 'WHATSAPP_VERIFY_TOKEN') ? $json.value : '';
try { if ($env.WHATSAPP_VERIFY_TOKEN) token = $env.WHATSAPP_VERIFY_TOKEN; } catch (e) {}
const ok = q['hub.mode'] === 'subscribe' && !!token && q['hub.verify_token'] === token;
return [{ json: { challenge: ok ? q['hub.challenge'] : 'forbidden', ok } }];
